import sys, requests, re, time, random, string

H = "https://spaceship.web.2026.sunshinectf.games"
s = requests.Session()
s.headers.update({"User-Agent":"Mozilla/5.0"})

def register():
    u = "rec"+"".join(random.choices(string.ascii_lowercase+string.digits,k=8))
    r = s.post(H+"/register", data={"username":u,"password":"pass1234"}, allow_redirects=False, timeout=20)
    return u, r.status_code, dict(r.cookies)

def scan(url):
    r = s.post(H+"/scan", data={"url":url}, allow_redirects=False, timeout=30)
    if r.status_code in (301,302) and "location" in r.headers:
        return r.headers["location"]
    return "BLOCKED:%d"%r.status_code

def result(path):
    r = s.get(H+path, timeout=30)
    t = r.text
    def g(pat):
        m = re.search(pat, t)
        return m.group(1).strip() if m else ""
    return {
        "status": g(r'Status</span><span class="v">([^<]*)'),
        "files": g(r'Files fetched</span><span class="v">([^<]*)'),
        "note": g(r'Drone note: ([^<]*)'),
        "img": g(r'<img src="(/screenshots/[^"]*)"'),
        "target": g(r'TARGET . <span>([^<]*)'),
    }

if __name__ == "__main__":
    u,c,cookies = register()
    print("user",u,c,cookies)
    for url in sys.argv[1:]:
        loc = scan(url)
        if loc.startswith("BLOCKED"):
            print(url, loc)
        else:
            res = result(loc)
            print(url, "->", res)
        time.sleep(0.5)
"}

