{"path": "/challenge/workspace/scan_many.py", "content": "#!/usr/bin/env python3
import requests, re, time, random, string, sys
from concurrent.futures import ThreadPoolExecutor

H = "https://spaceship.web.2026.sunshinectf.games"

def mk_session():
    s = requests.Session()
    s.headers.update({"User-Agent":"Mozilla/5.0"})
    u = "rec"+"".join(random.choices(string.ascii_lowercase+string.digits,k=8))
    s.post(H+"/register", data={"username":u,"password":"pass1234"}, allow_redirects=False, timeout=20)
    return s

def scan(s, url):
    try:
        r = s.post(H+"/scan", data={"url":url}, allow_redirects=False, timeout=40)
    except Exception as e:
        return (url, "EXC", str(e))
    if r.status_code in (301,302) and "location" in r.headers:
        loc = r.headers["location"]
        try:
            rr = s.get(H+loc, timeout=40)
            t = rr.text
            st = re.search(r'Status</span><span class="v">([^<]*)', t)
            nf = re.search(r'Files fetched</span><span class="v">([^<]*)', t)
            nt = re.search(r'Drone note: ([^<]*)', t)
            img = re.search(r'<img src="(/screenshots/[^"]*)"', t)
            return (url, st.group(1) if st else "", (nt.group(1) if nt else ""), (nf.group(1) if nf else ""), (img.group(1) if img else ""))
        except Exception as e:
            return (url,"GETEXC",str(e))
    return (url, "BLOCKED%d"%r.status_code)

def worker(arg):
    s, url = arg
    r = scan(s, url)
    print(r, flush=True)
    return r

if __name__ == "__main__":
    urls = sys.argv[1:]
    # distribute across a few sessions
    sessions = [mk_session() for _ in range(8)]
    tasks = [(sessions[i%8], u) for i,u in enumerate(urls)]
    with ThreadPoolExecutor(max_workers=6) as ex:
        list(ex.map(worker, tasks))
"}

